DO $$
DECLARE
  v_quiz_id_2 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أصول الدين - النبوة والأنعام والعصمة', 'إسلاميات', 'أصول الدين الخمسة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_2;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما هي أصول الدين الخمسة عند الشيعة الإمامية الاثني عشرية؟', '["التوحيد والعدل والنبوة والزكاة والمعاد","التوحيد والنبوة والإمامة والعدل والمعاد","التوحيد والنبوة والجهاد والأمر بالمعروف والمعاد","التوحيد والنبوة والصلاة والصوم والمعاد"]'::jsonb, 1, 20, 0, 'multi', 'أصول الدين عند الإمامية خمسة: التوحيد والعدل والنبوة والإمامة والمعاد، وهي ما يجب على المكلف اعتقاده بالدليل العقلي والنقلي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما الأصل الذي يُميّز المذهب الإمامي عن سائر المذاهب الإسلامية في أصول الدين؟', '["العدل","التوحيد","الإمامة","المعاد"]'::jsonb, 2, 20, 1, 'multi', 'الإمامة هي الأصل الذي يميز الشيعة الإمامية عن غيرهم، إذ يعدّونها أصلاً من أصول الدين يجب الاعتقاد به بالدليل، وليست مجرد مسألة فرعية فقهية.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما معنى النبوة باعتبارها أصلاً من أصول الدين؟', '["الإيمان بأن النبي محمداً أفضل البشر دون الحاجة إلى دليل","الاعتقاد بأن النبوة موروثة في ذرية النبي فقط","الاعتقاد بأن الملائكة أبلغوا الرسالة بدلاً من البشر","الإيمان بأن الله أرسل رسلاً لهداية البشر وتبليغ الأحكام الإلهية"]'::jsonb, 3, 20, 2, 'multi', 'النبوة في أصول الدين تعني الاعتقاد بأن الله تعالى أرسل أنبياء ورسلاً معصومين لهداية البشر وتبليغ الشريعة الإلهية، وختمهم بالنبي محمد صلى الله عليه وآله.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما الدليل العقلي الرئيسي على ضرورة النبوة والإرسال؟', '["قاعدة اللطف الإلهي التي تستوجب إرسال الأنبياء لكمال الإنسان","حاجة الملوك إلى مشروعية دينية","اتفاق الأمم على وجود الأنبياء تاريخياً","النصوص القرآنية دون الحاجة إلى دليل عقلي"]'::jsonb, 0, 20, 3, 'multi', 'يستدل علماء الإمامية على ضرورة النبوة بقاعدة اللطف، إذ يقتضي الحكمة الإلهية إرسال الأنبياء لتكميل عقول البشر وهدايتهم إلى ما يصلحهم في الدنيا والآخرة.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما المقصود بعصمة الأنبياء في الفقه الجعفري؟', '["حماية الأنبياء من الأمراض الجسدية فقط","انعدام الإرادة الحرة عند الأنبياء","تنزّه الأنبياء عن الذنوب والخطأ في تبليغ الرسالة والأفعال والأقوال","عدم جواز نقد الأنبياء من قِبَل العلماء"]'::jsonb, 2, 20, 4, 'multi', 'العصمة عند الإمامية تعني أن الأنبياء والأئمة منزّهون عن الذنوب الصغيرة والكبيرة، وعن الخطأ في تلقي الوحي وتبليغه، وذلك بلطف إلهي لا يُخلّ بالاختيار.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'كم عدد الأنبياء المذكور في الروايات الإمامية عموماً؟', '["خمسة آلاف نبي","مئة وعشرون ألف نبي","ثلاثمئة وثلاثة عشر نبياً","أربعة وعشرون ألف نبي"]'::jsonb, 1, 20, 5, 'multi', 'وردت في الروايات الإمامية أن عدد الأنبياء مئة وعشرون ألف نبي، وأن عدد الرسل منهم ثلاثمئة وثلاثة عشر رسولاً، كما في روايات الكافي للكليني.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما العلاقة بين أصل العدل وأصل النبوة في المنظومة العقدية الإمامية؟', '["العدل الإلهي يقتضي إرسال الأنبياء لأن تكليف البشر دون بيان ظلم","العدل يلغي الحاجة إلى الأنبياء","العدل لا علاقة له بالنبوة بل يتعلق بالثواب والعقاب فقط","النبوة مقدمة على العدل في الأهمية العقدية"]'::jsonb, 0, 20, 6, 'multi', 'العدل الإلهي عند الإمامية يستلزم أن لا يكلف الله البشر دون إقامة الحجة عليهم بإرسال الأنبياء، فلا عقاب دون بيان، وهذا يربط أصل العدل بأصل النبوة ربطاً وثيقاً.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'من هو خاتم الأنبياء والمرسلين عند المسلمين عامة والإمامية خاصة؟', '["الإمام علي بن أبي طالب عليه السلام","النبي عيسى بن مريم عليه السلام","النبي إبراهيم الخليل عليه السلام","النبي محمد بن عبد الله صلى الله عليه وآله وسلم"]'::jsonb, 3, 20, 7, 'multi', 'النبي محمد بن عبد الله صلى الله عليه وآله وسلم هو خاتم الأنبياء والمرسلين بنص القرآن الكريم في سورة الأحزاب آية 40، ولا نبي بعده وشريعته خاتمة الشرائع.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما الفرق بين النبي والرسول في الاصطلاح الكلامي الإمامي؟', '["الرسول يُوحى إليه والنبي يرى المنامات فقط","لا فرق بينهما في الاصطلاح الإمامي","الرسول من أُمر بتبليغ شريعة جديدة والنبي يُنبَأ ولا يُلزم بالتبليغ العام","النبي أعلى مرتبة من الرسول دائماً"]'::jsonb, 2, 20, 8, 'multi', 'في الكلام الإمامي يُفرَّق بين النبي والرسول، فالرسول مكلَّف بتبليغ شريعة جديدة وإقامة الدين في المجتمع، أما النبي فيُنبَأ بالوحي وقد لا يكون مأموراً بالتبليغ العام على الرأي المشهور.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'لماذا اشترط علماء الإمامية العصمةَ في الأئمة قياساً على الأنبياء؟', '["لأن العصمة شرط اجتماعي للقيادة السياسية فقط","لأن الإمام يقوم مقام النبي في حفظ الشريعة وتبليغها بعد انقطاع الوحي","لأن الأئمة أنبياء يوحى إليهم بشريعة جديدة","لأن الإمام لا يحتاج إلى علم بالشريعة"]'::jsonb, 1, 20, 9, 'multi', 'استدل علماء الإمامية كالشيخ المفيد والشيخ الطوسي على وجوب عصمة الإمام بأنه خليفة النبي في حفظ الشريعة وبيانها، فلو جاز عليه الخطأ لم تُؤمَن الشريعة من التحريف، وهذا نفس الدليل المستعمل في عصمة الأنبياء.', 'أصول الدين الخمسة');
END $$;



DO $$
DECLARE
  v_quiz_id_3 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أصول الدين - الإمامة ومفهوم النص والتعيين', 'إسلاميات', 'أصول الدين الخمسة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_3;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما هي أصول الدين الخمسة عند الإمامية الاثني عشرية؟', '["التوحيد والنبوة والإمامة والعدل والمعاد","التوحيد والنبوة والجهاد والصلاة والزكاة","الإيمان والإسلام والإحسان والتوكل والتوبة","التوحيد والعدل والنبوة والولاية والصيام"]'::jsonb, 0, 20, 0, 'multi', 'أصول الدين عند الإمامية الاثني عشرية خمسة: التوحيد والعدل والنبوة والإمامة والمعاد، وهي المسائل الاعتقادية الكبرى التي يجب على المكلف أن يعتقد بها عن دليل ونظر.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'لماذا أدرج علماء الإمامية ''الإمامة'' ضمن أصول الدين لا ضمن الفروع؟', '["لأنها فريضة عبادية كالصلاة والصوم","لأنها متعلقة بالأحكام الفقهية الفرعية","لأنها مسألة اعتقادية يتوقف عليها الإيمان الكامل ولا يصح التقليد فيها","لأن القرآن نص عليها في سورة الفاتحة"]'::jsonb, 2, 20, 1, 'multi', 'الإمامية يعدون الإمامة أصلاً من أصول الدين لأنها قضية اعتقادية كبرى ترتبط بالولاية الإلهية وامتداد النبوة، ولا يجوز فيها التقليد بل يجب الاعتقاد بها عن دليل ونظر كما أوضح ذلك الشيخ المفيد في ''أوائل المقالات''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما المقصود بـ''النص'' في مبحث الإمامة عند الإمامية؟', '["الإجماع الفقهي على اختيار الحاكم","تصريح النبي أو الإمام السابق بتعيين الإمام اللاحق بالاسم","الرأي العام للمسلمين في تعيين قائدهم","الآيات القرآنية المتعلقة بالصلاة والزكاة"]'::jsonb, 1, 20, 2, 'multi', 'النص في اصطلاح الإمامية يعني التصريح الصريح من النبي صلى الله عليه وآله أو من الإمام السابق بتعيين الإمام اللاحق باسمه وشخصه، كنص غدير خم على إمامة علي عليه السلام، وهو الركيزة الأساسية لمشروعية الإمامة.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما الآية القرآنية التي يستدل بها الإمامية على مبدأ التعيين الإلهي للإمام؟', '["''إنما وليكم الله ورسوله والذين آمنوا الذين يقيمون الصلاة ويؤتون الزكاة وهم راكعون''","''والذين جاهدوا فينا لنهدينهم سبلنا''","''قل هو الله أحد الله الصمد''","''وأقيموا الصلاة وآتوا الزكاة وأطيعوا الرسول''"]'::jsonb, 0, 20, 3, 'multi', 'آية الولاية في سورة المائدة (55) هي من أبرز الأدلة القرآنية التي يستشهد بها الإمامية على التعيين الإلهي، إذ يرون أنها نزلت في علي عليه السلام حين تصدق بخاتمه وهو راكع، وقد أوردها الطبرسي في ''مجمع البيان'' وغيره.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما الفرق الجوهري بين موقف الإمامية وموقف أهل السنة من مسألة تعيين الإمام؟', '["كلا الفريقين يتفقان على الشورى لكن يختلفان في التفاصيل","الإمامية يرون الانتخاب الشعبي، وأهل السنة يرون النص الإلهي","الإمامية يرون القرعة، وأهل السنة يرون الوراثة","الإمامية يرون التعيين الإلهي بالنص، وأهل السنة يرون الشورى أو الاختيار"]'::jsonb, 3, 20, 4, 'multi', 'الإمامية يؤكدون أن الإمامة منصب إلهي يتم بالنص والتعيين من الله ورسوله، بينما ذهب جمهور أهل السنة إلى أن الإمامة تثبت بالشورى والاختيار والبيعة، وهذا الخلاف موثق في كتب الكلام كـ''شرح المقاصد'' للتفتازاني و''تلخيص المحصل'' للطوسي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'كيف يُعرّف الشيخ المفيد الإمامة في كتابه ''أوائل المقالات''؟', '["مرتبة روحية خاصة لا تتعلق بالحكم والسياسة","رياسة عامة في أمور الدين والدنيا لشخص من البشر نيابةً عن النبي","منصب انتخابي يختاره العلماء بالإجماع","وظيفة دينية تقتصر على إمامة الصلاة وإصدار الفتاوى"]'::jsonb, 1, 20, 5, 'multi', 'عرّف الشيخ المفيد في ''أوائل المقالات'' الإمامة بأنها رياسة عامة في أمور الدين والدنيا لشخص من البشر نيابةً عن النبي صلى الله عليه وآله، وهو تعريف يُبرز شموليتها للبُعدين الديني والسياسي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما دلالة حديث الغدير ''من كنت مولاه فهذا علي مولاه'' في الاستدلال على الإمامة؟', '["يدل على النص الصريح بولاية علي وإمامته من بعد النبي","يدل على فضل علي دون تحديد منصب الإمامة له","يدل فقط على المحبة والمودة دون الإمارة والحكم","يدل على أفضلية علي في العبادة فحسب"]'::jsonb, 0, 20, 6, 'multi', 'يرى الإمامية أن حديث الغدير المروي في المصادر الإسلامية المختلفة نص جلي على إمامة علي عليه السلام، إذ أن لفظ ''مولى'' يعني الأولى بالتصرف والحاكم، وقد ناقش هذا الاستدلال بالتفصيل العلامة الحلي في ''نهج الحق وكشف الصدق''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما علاقة مبدأ ''العصمة'' بمفهوم التعيين الإلهي للإمام عند الإمامية؟', '["التعيين الإلهي لا علاقة له بالعصمة بل يكفي العدالة","العصمة خاصة بالأنبياء وليست مطلوبة في الأئمة","العصمة شرط في الإمام لأن الله لا يُعيّن إلا من يأمن الخطأ والمعصية في تبليغ الدين","العصمة فضيلة مستحبة لكنها ليست شرطاً في التعيين"]'::jsonb, 2, 20, 7, 'multi', 'يرى الإمامية أن العصمة شرط جوهري في الإمام لأن الغرض من الإمامة هو حفظ الدين وصون الشريعة، فلو لم يكن الإمام معصوماً لاحتاج إلى إمام آخر وتسلسل الأمر. وقد أكد هذا الخواجة نصير الدين الطوسي في ''تجريد الاعتقاد''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما الدليل العقلي الذي يسوقه الإمامية على وجوب الإمامة؟', '["الإمامة واجبة لأن النبي أوصى بها في وصيته الأخيرة فقط","قاعدة اللطف: الله يجب أن يُقرّب العباد إلى الطاعة بنصب إمام معصوم يهديهم","الإمامة واجبة من باب التقليد والاتباع للأعراف الإسلامية","الإمامة واجبة لأن الناس لا يستطيعون الاتفاق من تلقاء أنفسهم"]'::jsonb, 1, 20, 8, 'multi', 'يستدل الإمامية بقاعدة اللطف الإلهي على وجوب نصب الإمام، إذ اللطف الواجب على الله هو ما يُقرّب المكلف من الطاعة ويُبعده عن المعصية، ونصب الإمام المعصوم يحقق ذلك. وقد فصّل هذا الدليل الشيخ الطوسي في ''الاقتصاد فيما يتعلق بالاعتقاد''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما موقف العلامة الحلي من كون الإمامة أصلاً من أصول الدين في كتابه ''باب الحادي عشر''؟', '["رأى أنها تثبت بالإجماع الفقهي لا بالنص","قال إنها من فروع الدين ويجوز التقليد فيها","أهملها ولم يعدّها من أصول الاعتقاد","أكد أن الإمامة ركن عقدي من أركان الإيمان يجب البحث فيها بالعقل لا بالتقليد"]'::jsonb, 3, 20, 9, 'multi', 'العلامة الحلي في كتابه ''باب الحادي عشر'' جعل الإمامة ركناً أساسياً من أركان العقيدة الإمامية، وأوضح أن البحث فيها واجب عقلي لا يجوز فيه التقليد، لأنها تتصل بضرورة وجود الحجة على الخلق في كل زمان.', 'أصول الدين الخمسة');
END $$;



DO $$
DECLARE
  v_quiz_id_4 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أصول الدين - المعاد والحساب والبرزخ', 'إسلاميات', 'أصول الدين الخمسة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_4;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما هو المعاد في العقيدة الإمامية الاثني عشرية؟', '["عودة الأرواح إلى الدنيا قبل يوم القيامة","فناء الروح مع الجسد عند الموت","انتقال الروح من جسد إلى آخر بعد الموت","بعث الإنسان بجسده وروحه للحساب والجزاء يوم القيامة"]'::jsonb, 3, 20, 0, 'multi', 'المعاد في العقيدة الإمامية هو إعادة الإنسان بجسده وروحه معاً يوم القيامة للحساب والجزاء، وهو من أصول الدين الخمسة التي لا يتم الإيمان إلا بها.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما هي أصول الدين الخمسة عند الشيعة الإمامية؟', '["التوحيد والنبوة والإمامة والعدل والجهاد","الصلاة والصيام والزكاة والحج والجهاد","التوحيد والعدل والنبوة والإمامة والمعاد","التوحيد والنبوة والمعاد والصلاة والزكاة"]'::jsonb, 2, 20, 1, 'multi', 'أصول الدين عند الشيعة الإمامية خمسة هي: التوحيد والعدل والنبوة والإمامة والمعاد، وهي الأسس العقدية التي يُبنى عليها الإيمان الكامل.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما المقصود بالبرزخ في العقيدة الإسلامية الشيعية؟', '["عالم ما بعد الحشر والحساب","عالم ما بين الموت والبعث يوم القيامة","المرحلة التي تسبق الخلق الأول للإنسان","مرحلة الصراط والميزان"]'::jsonb, 1, 20, 2, 'multi', 'البرزخ هو العالم الواسط بين الموت والبعث يوم القيامة، وقد أثبته القرآن الكريم بقوله تعالى ''ومن ورائهم برزخ إلى يوم يبعثون''، ويُعدّ مرحلة يلقى فيها الإنسان جزاءً أولياً على أعماله.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ماذا يعني مبدأ العدل الإلهي في أصول الدين الإمامية؟', '["أن الله منزّه عن الظلم وأفعاله كلها قائمة على الحكمة والعدل","أن الله يجازي الناس في الدنيا فقط","أن الله يساوي بين المؤمن والكافر في الثواب","أن العدل خاصية بشرية لا تنسب إلى الله"]'::jsonb, 0, 20, 3, 'multi', 'العدل الإلهي عند الإمامية يعني أن الله سبحانه منزّه عن كل ظلم وقبيح، وأن جميع أفعاله قائمة على الحكمة والعدل، وهذا يميّز المذهب الإمامي والمعتزلة عن الأشاعرة في هذه المسألة.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما الذي يميّز عقيدة الإمامية في المعاد عن بعض الفرق الأخرى؟', '["اعتقادها أن المعاد يكون في الدنيا لا في الآخرة","إيمانها بأن المعاد روحاني فقط دون الجسد","إنكارها للحساب والجزاء في الآخرة","إيمانها بالمعاد الجسماني والروحاني معاً"]'::jsonb, 3, 20, 4, 'multi', 'تعتقد الإمامية بالمعاد الجسماني والروحاني معاً، أي أن الإنسان يُبعث بجسده المادي وروحه يوم القيامة، وهذا ما يفترق به الإمامية عن من يقول بالمعاد الروحاني المحض.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما هو الميزان في عقيدة المعاد الإسلامية؟', '["الشفاعة التي يقدمها الأنبياء للمذنبين","كتاب تُسجّل فيه الأعمال","المقياس الذي تُوزن به أعمال العباد يوم القيامة","الصراط الممدود على النار"]'::jsonb, 2, 20, 5, 'multi', 'الميزان هو المقياس الإلهي الذي تُوزن به أعمال العباد يوم القيامة، وقد أشار إليه القرآن الكريم في قوله ''ونضع الموازين القسط ليوم القيامة''، وهو من مراحل الحساب الأخروي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما المقصود بـ ''الصراط'' في عقيدة المعاد عند الإمامية؟', '["مرحلة السؤال في القبر","الجسر الممدود على جهنم الذي يعبر عليه الناس للوصول إلى الجنة","طريق الجنة في الدنيا","كتاب يُقرأ فيه سجل الأعمال"]'::jsonb, 1, 20, 6, 'multi', 'الصراط هو الجسر الممدود على جهنم الذي يجب على الناس عبوره للوصول إلى الجنة يوم القيامة، وهو من الحقائق الأخروية الثابتة في عقيدة الإمامية استناداً إلى الروايات والآيات القرآنية.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما حكم الشفاعة في عقيدة الإمامية الاثني عشرية؟', '["منكرة كلياً لأنها تنافي العدل الإلهي","خاصة بالأنبياء فقط دون الأئمة والصالحين","تشمل جميع الناس مؤمنين وكافرين بلا استثناء","ثابتة بإذن الله للأنبياء والأئمة والشهداء لأهل الإيمان"]'::jsonb, 3, 20, 7, 'multi', 'الشفاعة ثابتة في عقيدة الإمامية بإذن الله تعالى، وتشمل الأنبياء والأئمة والشهداء والعلماء، وهي خاصة بأهل الإيمان الذين ارتكبوا الذنوب، استناداً لقوله تعالى ''ولا يشفعون إلا لمن ارتضى''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما الذي تعتقده الإمامية بشأن عذاب القبر في مرحلة البرزخ؟', '["يعتبرونه من الأمور الموهومة التي لا أساس لها","يثبتونه للكافرين فقط دون المؤمنين المذنبين","يثبتونه استناداً للأحاديث والآيات وهو جزء من حياة البرزخ","ينكرونه كلياً لأنه لم يرد في القرآن"]'::jsonb, 2, 20, 8, 'multi', 'تثبت الإمامية عذاب القبر ونعيمه استناداً للآيات القرآنية كقوله تعالى في آل فرعون ''النار يُعرضون عليها غدواً وعشياً'' وللأحاديث المروية عن أهل البيت عليهم السلام، وهو من حقائق عالم البرزخ.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما الفرق بين الحشر والبعث في المصطلح العقدي الإمامي؟', '["البعث هو إعادة الحياة للأموات والحشر هو جمعهم للحساب في يوم القيامة","هما مصطلحان مترادفان تماماً لا فرق بينهما","البعث يكون روحانياً والحشر جسمانياً","الحشر يخص المؤمنين فقط والبعث يشمل الجميع"]'::jsonb, 0, 20, 9, 'multi', 'البعث هو إعادة الحياة للأموات بجسدهم وروحهم يوم القيامة، أما الحشر فهو جمع الخلائق في موقف واحد للحساب والجزاء، وإن كان بعض العلماء يستخدمهما بمعنى متقارب إلا أن ثمة فرقاً دقيقاً بينهما في توظيفهما العقدي.', 'أصول الدين الخمسة');
END $$;



DO $$
DECLARE
  v_quiz_id_5 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('مفهوم الإمامة وأدلة العصمة الشرعية', 'إسلاميات', 'الإمامة والعصمة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_5;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما التعريف الاصطلاحي للإمامة في الفقه الجعفري؟', '["مرتبة شرفية تُمنح لآل البيت دون صلاحيات تشريعية","وظيفة دينية تقتصر على إقامة الصلاة وتعليم الشريعة","منصب سياسي يُنتخب فيه الأفضل من المسلمين","رئاسة عامة في أمور الدين والدنيا خلافةً عن النبي"]'::jsonb, 3, 20, 0, 'multi', 'عرّف علماء الإمامية الإمامة بأنها رئاسة عامة إلهية في أمور الدين والدنيا خلافةً عن النبي صلى الله عليه وآله، وهذا ما أكده الشيخ المفيد في أوائل المقالات والعلامة الحلي في كشف المراد.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما الدليل القرآني الرئيسي الذي يستند إليه الإمامية لإثبات عصمة الأئمة؟', '["آية التطهير: ''إنما يريد الله ليذهب عنكم الرجس أهل البيت''","آية الولاية: ''النبي أولى بالمؤمنين من أنفسهم''","آية الأمانة: ''إن الله يأمركم أن تؤدوا الأمانات إلى أهلها''","آية الشورى: ''وأمرهم شورى بينهم''"]'::jsonb, 0, 20, 1, 'multi', 'يستدل الإمامية بآية التطهير (الأحزاب:33) على عصمة أهل البيت، إذ إن نفي الرجس المطلق يستلزم العصمة عن الذنب والخطأ، وقد وثّق ذلك الشيخ الطوسي في التبيان والطبرسي في مجمع البيان.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما الحديث النبوي الذي يعدّه الإمامية دليلاً قاطعاً على إمامة علي بن أبي طالب بعد النبي مباشرةً؟', '["حديث الثقلين: ''إني تارك فيكم الثقلين''","حديث المنزلة: ''أنت مني بمنزلة هارون من موسى''","حديث الغدير: ''من كنت مولاه فهذا علي مولاه''","حديث السفينة: ''مثل أهل بيتي فيكم كمثل سفينة نوح''"]'::jsonb, 2, 20, 2, 'multi', 'حديث الغدير المروي في صحيح مسلم ومسند أحمد وغيرهما هو الأبرز لدى الإمامية في إثبات الإمامة المباشرة لعلي، وقد استدل به الشيخ المفيد والسيد المرتضى استدلالاً مفصلاً.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'كيف يُفسّر علماء الإمامية العقلي لضرورة عصمة الإمام؟', '["لأن الشعب لا يثق إلا بمن لا يُخطئ في أمور الدنيا","لأن غير المعصوم يحتاج إلى مُصحِّح آخر فيلزم التسلسل","لأن الإمام مفوَّض بالتشريع ولا حاجة للعصمة في التطبيق","لأن الإمام يجب أن يكون من قريش فحسب"]'::jsonb, 1, 20, 3, 'multi', 'يقرر الخواجه نصير الدين الطوسي في تجريد الاعتقاد أن الإمام لو لم يكن معصوماً لاحتاج إلى إمام معصوم يُصوِّبه فيلزم التسلسل أو الدور، وهو برهان عقلي لإثبات ضرورة العصمة.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما مفهوم العصمة في الاصطلاح الكلامي الإمامي؟', '["إجبار رباني يسلب المعصوم الإرادة والاختيار","مجرد تنزيه اجتماعي يُعطي المعصوم سمعة حسنة","صفة وراثية تنتقل عبر الدم من النبي إلى أبنائه فقط","لطف إلهي يجعل المعصوم قادراً على ترك المعصية اختياراً مع القدرة عليها"]'::jsonb, 3, 20, 4, 'multi', 'عرّف الشيخ المفيد في تصحيح الاعتقاد والعلامة الحلي في كشف المراد العصمة بأنها لطف من الله يجعل صاحبه داعياً إلى ترك القبيح مع بقاء القدرة عليه، فلا تنافي الاختيار.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما عدد الأئمة الذين يعتقد الإمامية الاثنا عشرية بإمامتهم؟', '["اثنا عشر إماماً من علي بن أبي طالب إلى المهدي المنتظر","سبعة أئمة ينتهون بإسماعيل بن جعفر","أحد عشر إماماً وتنتهي الإمامة بالحسن العسكري","عشرة أئمة يبدأون بالحسن ويختمون بالرضا"]'::jsonb, 0, 20, 5, 'multi', 'تعتقد الإمامية الاثنا عشرية بإمامة اثني عشر إماماً تبدأ بعلي بن أبي طالب وتنتهي بمحمد بن الحسن المهدي المنتظر، وهو ما أجمع عليه علماؤهم كالشيخ الصدوق في كمال الدين.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما دلالة حديث الثقلين على إمامة أهل البيت وعصمتهم؟', '["دلالته مقتصرة على وجوب محبة آل البيت دون اتباعهم","الأمر بالتمسك بهم مع القرآن دليل على انتفاء الخطأ عنهم","الحديث يدل على فضلهم الأخلاقي لا على إمامتهم السياسية","الحديث موضوع ولا يُحتج به في مسائل الإمامة"]'::jsonb, 1, 20, 6, 'multi', 'يستدل علماء الإمامية كالسيد الخوئي في البيان بأن الأمر بالتمسك بأهل البيت قرين القرآن يقتضي أن يكون قولهم حجة مطلقة، وهذا لا يتم إلا مع عصمتهم من الخطأ.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما الفرق الجوهري بين مفهوم الإمامة عند الإمامية ومفهوم الخلافة عند أهل السنة؟', '["الإمامة تقتصر على الجانب الديني، والخلافة على الجانب السياسي","الإمامة وراثية من الأب للابن دون اشتراط العصمة","لا فرق جوهري بينهما إلا في التسمية والشكل","الإمامة منصب إلهي بالنص والعصمة، والخلافة بشرية بالاختيار والشورى"]'::jsonb, 3, 20, 7, 'multi', 'يرى الإمامية أن الإمامة منصب إلهي يُعيَّن فيه الإمام بنص من الله عبر النبي ويشترط فيه العصمة، بينما يرى أهل السنة أن الخلافة تثبت بالاختيار والشورى دون اشتراط العصمة، وهو ما أوضحه السيد المرتضى في الشافي.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما الموقف الإمامي من عصمة الإمام في مجال تلقي الوحي والتشريع؟', '["الأئمة مفوَّضون بالتشريع ويجوز لهم تعديل الأحكام القرآنية","الأئمة يتلقون وحياً تشريعياً مستقلاً يضاف إلى القرآن","الأئمة لا يتلقون وحياً تشريعياً جديداً لكنهم معصومون في بيان ما ورثوه من علم النبي","الأئمة لا يختلفون عن بقية العلماء إلا في النسب الشريف"]'::jsonb, 2, 20, 8, 'multi', 'يُقرر الشيخ الصدوق والشيخ المفيد أن الأئمة لا يتلقون وحياً تشريعياً جديداً بعد النبي، بل يحملون علمه ويُبيّنونه بعصمة تامة، وهذا يميزهم عن النبوة مع إثبات حجية قولهم.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما المقصود بمبدأ ''اللطف'' في علم الكلام الإمامي وصلته بوجوب نصب الإمام؟', '["حق للعباد يُطالبون به دون أن يكون واجباً على الله","وجوب على الله إيجاد ما يُقرّب العباد إلى الطاعة ويُبعدهم عن المعصية","فضل إضافي من الله لا يترتب على تركه أي محذور عقلي","مبدأ صوفي يتعلق بالمحبة الإلهية لا بالتكاليف الشرعية"]'::jsonb, 1, 20, 9, 'multi', 'يُعرّف السيد المرتضى في الذخيرة والشيخ الطوسي في الاقتصاد اللطفَ بأنه ما يكون المكلف معه أقرب إلى فعل الطاعة وأبعد عن المعصية، ويستنتجون وجوب نصب الإمام المعصوم تحقيقاً لهذا اللطف الإلهي.', 'الإمامة والعصمة');
END $$;



DO $$
DECLARE
  v_quiz_id_6 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أدلة إمامة الأئمة الاثني عشر (ع) نصاً وتاريخاً', 'إسلاميات', 'الإمامة والعصمة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_6;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما المقصود بمبدأ العصمة في الفكر الإمامي الاثني عشري؟', '["أن الإمام يعصم نفسه بالاجتهاد الشخصي","أن العصمة تعني الاستحالة الطبيعية للذنب","أن الإمام يخطئ لكن يتوب فوراً","أن الإمام محفوظ من الخطأ والمعصية بتوفيق إلهي خاص"]'::jsonb, 3, 20, 0, 'multi', 'العصمة عند الإمامية هي لطف إلهي يمنح الإمام القدرة على اجتناب الذنوب والأخطاء في التبليغ والعمل، وهي ليست قسراً بل اختياراً مؤيداً بنعمة الله، كما أكده الشيخ المفيد في كتاب ''أوائل المقالات''.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'أي آية قرآنية استدل بها علماء الإمامية على اشتراط العصمة في الإمام استناداً إلى عدم نيل العهد الظالمين؟', '["آية ''أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم''","آية ''لا ينال عهدي الظالمين''","آية ''إنما وليكم الله ورسوله''","آية ''اليوم أكملت لكم دينكم''"]'::jsonb, 1, 20, 1, 'multi', 'استدل علماء الإمامية كالشيخ الطوسي والعلامة الحلي بقوله تعالى في سورة البقرة آية 124: ''لا ينال عهدي الظالمين''، ليثبتوا أن الإمامة لا تجوز لمن ارتكب الظلم ولو لحظة، فتنحصر في المعصوم.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما الحديث النبوي الذي استشهد به الإماميون على تحديد عدد الأئمة باثني عشر إماماً؟', '["حديث الثقلين المروي عن جابر","حديث ''من مات ولم يعرف إمام زمانه مات ميتة جاهلية''","حديث ''لا يزال الدين قائماً حتى تقوم الساعة ويكون اثنا عشر خليفة كلهم من قريش''","حديث ''أنا مدينة العلم وعلي بابها''"]'::jsonb, 2, 20, 2, 'multi', 'حديث الاثني عشر خليفة أو أميراً مروي في صحيح البخاري ومسلم وغيرهما عن جابر بن سمرة، وقد وظّفه علماء الإمامية كابن بابويه القمي في ''كمال الدين'' دليلاً على انحصار الخلافة الحقة في الأئمة الاثني عشر.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما العلاقة بين العصمة والنص في منظومة الإمامة الجعفرية؟', '["النص الإلهي أو النبوي على الشخص المعصوم هو الطريق الوحيد لمعرفة الإمام","العصمة والنص مستقلان ولا يرتبطان ببعضهما","العصمة تغني عن النص لأن المعصوم يُعرف بأعماله","النص وحده يكفي لإثبات الإمامة دون الحاجة إلى العصمة"]'::jsonb, 0, 20, 3, 'multi', 'يرى المتكلمون الإماميون كالشيخ المفيد والخواجة نصير الدين الطوسي في ''تجريد الاعتقاد'' أن العقل يُثبت ضرورة العصمة، لكن تعيين الشخص المعصوم لا يمكن إلا بنص من الله أو رسوله أو الإمام السابق.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما حديث الغدير وأهميته في إثبات إمامة أمير المؤمنين علي (ع) نصاً؟', '["حديث خطب به أبو بكر بعد وفاة النبي","حديث روي عن علي نفسه يُعلن فيه إمامته","حديث قاله النبي في مسجد المدينة قبيل وفاته","حديث أعلن فيه النبي ولاية علي في غدير خم عند عودته من حجة الوداع"]'::jsonb, 3, 20, 4, 'multi', 'في الثامن عشر من ذي الحجة سنة عشر للهجرة، أعلن النبي (ص) في غدير خم قائلاً: ''من كنت مولاه فهذا علي مولاه''. وقد وثّق العلامة الأميني هذا الحديث في موسوعة ''الغدير'' من طرق أهل السنة والشيعة، وعدّه الإماميون النص الجلي على إمامة علي (ع).', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما الدليل العقلي الذي ساقه الخواجة نصير الدين الطوسي على وجوب عصمة الإمام في ''تجريد الاعتقاد''؟', '["أن العصمة دليل حسي يُعرف بالمعجزات فقط","أن الإمام غير المعصوم يحتاج إلى إمام آخر يصحح أخطاءه فيتسلسل الأمر إلى ما لا نهاية","أن الإمام يُنتخب بالشورى فلا حاجة للعصمة","أن الإمام المعصوم يتميز بعلامات ظاهرة لا تخطئها العيون"]'::jsonb, 1, 20, 5, 'multi', 'استخدم الخواجة نصير الدين الطوسي في ''تجريد الاعتقاد'' حجة التسلسل: إذا كان الإمام غير معصوم احتاج إلى إمام يقوم بتصحيحه، وذاك إن لم يكن معصوماً احتاج لآخر، وهكذا إلى ما لا نهاية، فوجب أن ينتهي الأمر إلى معصوم.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما النص الوارد في حديث الثقلين الدال على الحجية الدائمة لأهل البيت (ع)؟', '["''تركت فيكم ما إن تمسكتم به لن تضلوا: كتاب الله وعترتي أهل بيتي''","''أهل بيتي كسفينة نوح من ركبها نجا''","''كتاب الله وسنتي ولن يفترقا''","''علي مع الحق والحق مع علي''"]'::jsonb, 0, 20, 6, 'multi', 'حديث الثقلين المروي بطرق متعددة في مصادر الفريقين، ومنها مسند أحمد وسنن الترمذي، ينص على أن النبي (ص) خلّف الكتاب والعترة ولن يفترقا حتى يردا عليه الحوض، وقد استدل به الإماميون على استمرار الحجية في أئمة أهل البيت (ع).', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'لماذا يرى علماء الإمامية أن الإمامة من أصول الدين لا من فروعه؟', '["لأنها تثبت بالشورى والاتفاق العام","لأن الفقهاء قرروا ذلك باجتهادهم الجماعي","لأنها منصب إلهي يرتبط بحفظ الدين وهداية البشر استمراراً للنبوة","لأنها تتعلق بالعبادات العملية كالصلاة والصوم"]'::jsonb, 2, 20, 7, 'multi', 'يذهب علماء الإمامية كالشيخ المفيد في ''الإرشاد'' والعلامة الحلي في ''باب الحادي عشر'' إلى أن الإمامة رئاسة إلهية عامة لحفظ الشريعة وهداية الأمة، وهي امتداد لوظيفة النبوة، فلا تثبت بالاختيار البشري بل بالنص الإلهي.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'أي مؤلَّف كلامي جمع أدلة إمامة الأئمة الاثني عشر (ع) نصاً على نصاً من المصادر الروائية؟', '["''نهج البلاغة'' لجمع خطب الإمام علي (ع)","''الكافي'' للكليني في باب الحجة","''الشافي في الإمامة'' للسيد المرتضى","''تهذيب الأحكام'' للشيخ الطوسي"]'::jsonb, 1, 20, 8, 'multi', 'خصص الشيخ الكليني في كتابه ''الكافي'' أبواباً مفصّلة تحت عنوان ''كتاب الحجة'' تجمع الروايات المسندة على النص على كل إمام من أئمة أهل البيت (ع) بالاسم، من أمير المؤمنين حتى الإمام المهدي (عج).', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما موقف الإمام جعفر الصادق (ع) من مسألة تحديد الإمام بالنص كما رواه الكليني في ''الكافي''؟', '["قال إن الإمامة تثبت للأفضل علماً بين أبناء الإمام","أكد أن الأمة تختار الإمام بشرط أن يكون هاشمياً","أجاز اختيار الإمام بإجماع العلماء إن غاب النص","قرر أن الإمامة لا تنتقل إلا بنص الإمام السابق على خلفه"]'::jsonb, 3, 20, 9, 'multi', 'روى الكليني في ''الكافي'' عن الإمام الصادق (ع) أحاديث صريحة تبيّن أن الإمامة عهد من الله ينتقل بنص الإمام الحي على من يخلفه، وأن الأمة لا حق لها في الاختيار، وهو ما شكّل ركيزة في الفكر الإمامي الاثني عشري.', 'الإمامة والعصمة');
END $$;



DO $$
DECLARE
  v_quiz_id_7 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('العصمة وشروط الإمام وصفاته الإلهية', 'إسلاميات', 'الإمامة والعصمة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_7;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما المقصود بعصمة الإمام في العقيدة الإمامية الاثني عشرية؟', '["قدرة الإمام على الدفاع عن نفسه في المعارك","صون الإمام من الخطأ والذنب في تبليغ الأحكام وتطبيقها","تمتع الإمام بالسلطة السياسية المطلقة","علم الإمام الواسع بعلوم الدنيا فحسب"]'::jsonb, 1, 20, 0, 'multi', 'العصمة عند الإمامية تعني صون الإمام من الخطأ والنسيان والذنب في جميع جوانب التبليغ والتطبيق والسلوك، وهي شرط جوهري في الإمام كما قرره الشيخ المفيد والعلامة الحلي.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'من أي مصدر يستمد الإمام عصمته وفق العقيدة الإمامية؟', '["من فضل إلهي خاص يمنحه الله تعالى للإمام","من تزكية الأمة له بالانتخاب والبيعة","من إجماع العلماء والفقهاء على صلاحه","من خلال الاجتهاد الفردي الطويل"]'::jsonb, 0, 20, 1, 'multi', 'العصمة موهبة إلهية يختص الله بها من يشاء من عباده، فالإمام لا يكتسبها بجهده بل يُودعها الله فيه بلطفه، كما صرح بذلك المحقق الطوسي في تجريد الاعتقاد.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما الشرط الذي يميز الإمام الاثني عشري عن سائر العلماء والفقهاء وفق العلامة الحلي؟', '["الحصول على أعلى درجات الاجتهاد الفقهي","النسب القرشي من بني أمية","الشجاعة في الحرب والقيادة العسكرية","العصمة من الخطأ والذنب والنسيان"]'::jsonb, 3, 20, 2, 'multi', 'صرّح العلامة الحلي في كتاب ''كشف المراد'' بأن العصمة شرط لازم في الإمام يميزه عن غيره، إذ لا يصح أن يكون قائد الأمة الدينية والسياسي معرضاً للخطأ والذنب.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما موقف الإمامية من إمامة من ليس بمعصوم؟', '["تجوز إمامته في الشؤون الدنيوية دون الدينية","لا تصح إمامته مطلقاً لأن العصمة شرط أساسي","يمكن قبول إمامته بشرط الإجماع","تصح إمامته إذا كان عادلاً وعالماً"]'::jsonb, 1, 20, 3, 'multi', 'يرى الإمامية أن الإمامة الحقة لا تنعقد لغير المعصوم، لأن الغرض من الإمامة هو الحفاظ على الشريعة من التحريف والخطأ، وهذا لا يتحقق إلا بالمعصوم، كما قرره الشيخ المفيد في ''الإرشاد''.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما معنى قول الإمامية بأن الإمام يعلم متى يموت ولا يموت إلا باختياره؟', '["أن الإمام يملك القدرة على تحديد أجله الطبيعي بإرادته","أن الإمام لا يخضع لقوانين الطبيعة البشرية","أن الإمام مُطلع بعلم إلهي على أجله فيكون موته شهادة واعية","أن الإمام لا يمرض ولا يتألم"]'::jsonb, 2, 20, 4, 'multi', 'تعني هذه العقيدة أن الإمام يُفاض عليه علم بأجله فيستقبل الشهادة باختيار واعٍ، لا أن يتحكم في القدر المحتوم، وهو ما أشار إليه الكليني في ''الكافي'' في باب أن الأئمة يعلمون متى يموتون.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'كيف يستدل الإمامية على العصمة من الآية الكريمة ''لا ينال عهدي الظالمين''؟', '["الآية تنفي الإمامة عمن ارتكب ظلماً ولو مرة في حياته فوجب العصمة","الظالم هنا يقصد به الكافر فقط فلا يُعيَّن إماماً","الظلم في الآية محصور بالظلم السياسي دون الذنوب الأخرى","الآية خاصة بإمامة بني إسرائيل وليست حجة في الإسلام"]'::jsonb, 0, 20, 5, 'multi', 'استدل العلامة الحلي وغيره بأن الآية تنفي الإمامة عن الظالم، وكل من أذنب ولو ذنباً واحداً فقد ظلم نفسه، فلا يصح أن يكون إماماً، وهذا يقتضي أن يكون الإمام معصوماً طوال حياته.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما العلم الذي يتمتع به الإمام المعصوم وفق روايات الكافي للكليني؟', '["علم القرآن الكريم حفظاً وتفسيراً فحسب","علم ما كان وما يكون وما هو كائن حتى تقوم الساعة","علم الحلال والحرام دون علم الغيب","علم ما كان فقط من أخبار السابقين"]'::jsonb, 1, 20, 6, 'multi', 'جاء في ''الكافي'' للكليني في باب أن الأئمة عندهم جميع العلوم التي خرجت إلى الملائكة والأنبياء والرسل، أن الإمام يعلم ما كان وما يكون وما هو كائن إلى يوم القيامة، وهو علم موهوب من الله.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما الفرق بين عصمة الأنبياء وعصمة الأئمة في العقيدة الإمامية وفق الشيخ المفيد؟', '["عصمة الأنبياء مطلقة بينما عصمة الأئمة مقيدة بالشؤون الدينية","الأنبياء معصومون قبل النبوة أما الأئمة فمعصومون بعد تعيينهم فقط","لا فرق بينهما في المرتبة والمستوى","عصمة الأنبياء تشمل تبليغ الوحي وعصمة الأئمة تشمل حفظ الشريعة وتطبيقها"]'::jsonb, 3, 20, 7, 'multi', 'أوضح الشيخ المفيد في ''أوائل المقالات'' أن الأنبياء معصومون في تلقي الوحي وتبليغه، بينما الأئمة معصومون في حفظ الشريعة وتفسيرها وتطبيقها وقيادة الأمة، وكلاهما معصوم من الذنوب والخطأ.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'لماذا يشترط الإمامية أن يكون الإمام منصوصاً عليه من قِبَل الله أو النبي أو الإمام السابق؟', '["لأن العصمة لا تُعرف إلا بالنص الإلهي إذ لا يطلع عليها البشر","لأن الأمة غير قادرة على الاختيار السليم دون وصاية إلهية","لأن الاختيار الشعبي يؤدي إلى الفتنة والاقتتال","لأن الأئمة من نسل قريش ولا بد من توثيق النسب"]'::jsonb, 0, 20, 8, 'multi', 'يستند الإمامية إلى أن العصمة صفة باطنية لا يعلمها إلا الله، ولا يمكن للبشر التحقق منها، فلا بد من نص إلهي أو نبوي يعيّن المعصوم، وهو ما قرره المحقق الطوسي وابن ميثم البحراني.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما موقف الإمامية من نسيان الإمام المعصوم للأحكام الشرعية؟', '["يجوز على الإمام النسيان في الشؤون الدنيوية دون الدينية","النسيان جائز على الإمام كالبشر العاديين لأنه بشر","الإمام معصوم من النسيان في الأحكام الشرعية لأن نسيانه يُضل الأمة","النسيان جائز لكن الإمام يُنبَّه إليه فوراً بالوحي"]'::jsonb, 2, 20, 9, 'multi', 'ذهب الإمامية إلى أن الإمام لا ينسى الأحكام الشرعية لأن نسيانه يُفضي إلى ضلال الأمة وتناقض السنة، وهو ما ينافي الغرض من الإمامة، كما أكد ذلك الشيخ المفيد والعلامة الحلي في مصنفاتهم العقدية.', 'الإمامة والعصمة');
END $$;



DO $$
DECLARE
  v_quiz_id_8 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الصلاة الواجبة والمستحبة ومبطلاتها', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_8;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما هو عدد الصلوات اليومية الواجبة في الفقه الجعفري؟', '["خمس صلوات","ست صلوات","ثلاث صلوات","أربع صلوات"]'::jsonb, 0, 20, 0, 'multi', 'الصلوات اليومية الواجبة خمس: الصبح والظهر والعصر والمغرب والعشاء، وهذا متفق عليه في الفقه الجعفري.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'كم عدد ركعات صلاة الصبح في الفقه الجعفري؟', '["أربع ركعات","ركعة واحدة","ثلاث ركعات","ركعتان"]'::jsonb, 3, 20, 1, 'multi', 'صلاة الصبح ركعتان، وهي من الصلوات التي لا تُقصر في السفر لأنها أصلاً ركعتان.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما الحكم الشرعي لصلاة الجمعة في زمن الغيبة الكبرى عند أكثر فقهاء الإمامية؟', '["مستحبة","واجبة تخييرية بينها وبين الظهر","واجبة عينية","محرمة"]'::jsonb, 1, 20, 2, 'multi', 'ذهب أكثر فقهاء الإمامية إلى أن صلاة الجمعة في زمن الغيبة واجبة تخييرية، أي يتخير المكلف بين إقامتها وبين صلاة الظهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'أيٌّ من الآتي يُعدّ من مبطلات الصلاة في الفقه الجعفري؟', '["الحدث الأصغر أثناء الصلاة","السعال الاضطراري","البكاء خشيةً من الله","الالتفات اليسير بالوجه"]'::jsonb, 0, 20, 3, 'multi', 'الحدث الأصغر كالبول أو الريح أثناء الصلاة يُبطلها، بخلاف البكاء خشيةً من الله والالتفات اليسير والسعال الاضطراري فلا تُبطل الصلاة.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما الذي يُعدّ شرطاً في صحة الصلاة من حيث القبلة عند الإمامية؟', '["لا يشترط استقبال القبلة في الصلاة المفروضة","استقبال عين الكعبة فقط","الاستقبال الظني للقبلة بالاجتهاد عند تعذر اليقين","الصلاة نحو الشمال دائماً"]'::jsonb, 2, 20, 4, 'multi', 'يشترط استقبال القبلة في الصلاة، ويكفي الظن الحاصل بالاجتهاد أو الأمارات عند تعذر اليقين، وإلا صلى إلى الجهات الأربع إن لم يتمكن من الاجتهاد.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
