  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما هي النافلة اليومية المرتبطة بصلاة الفجر والتي يُؤكد عليها الفقه الجعفري؟', '["صلاة الأوابين","ركعتا الفجر (نافلة الفجر)","صلاة الليل","صلاة الوتر"]'::jsonb, 1, 20, 6, 'multi', 'ركعتا الفجر هما النافلة المؤكدة التي تُصلى قبل فريضة الصبح، وهي من النوافل الراتبة المشددة عليها في الروايات الجعفرية.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'كم عدد ركعات نافلة الليل الكاملة في الفقه الجعفري؟', '["ست ركعات","ثلاث عشرة ركعة","إحدى عشرة ركعة","ثماني ركعات"]'::jsonb, 2, 20, 7, 'multi', 'نافلة الليل إحدى عشرة ركعة: ثماني ركعات صلاة الليل، وركعتا الشفع، وركعة الوتر، وهذا ما أكدته روايات أهل البيت عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما الحكم في من شك بين الثلاث والأربع في الصلاة الرباعية في الفقه الجعفري؟', '["يبني على الأكثر ويتم الصلاة ثم يحتاط بركعة منفصلة","يعيد الصلاة من البداية","شكه لا حكم له","يبني على الأقل ويأتي بركعة"]'::jsonb, 0, 20, 8, 'multi', 'من شك بين الثلاث والأربع يبني على الأربع ويُتم صلاته، ثم يأتي بصلاة الاحتياط ركعة قائماً أو ركعتين جالساً، وهذا من أحكام الشكوك الصحيحة.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'أيٌّ من الآتي لا يُبطل الصلاة في الفقه الجعفري؟', '["الضحك القهقهي عمداً","ترك ركن من أركان الصلاة عمداً","استدبار القبلة عمداً","نسيان التشهد الأخير والتذكر بعد السلام"]'::jsonb, 3, 20, 9, 'multi', 'نسيان التشهد الأخير والتذكر بعده لا يُبطل الصلاة، بل يجب قضاؤه وسجدتا السهو. أما القهقهة وترك الركن عمداً واستدبار القبلة فكلها مبطلات.', 'فقه جعفري عملي');
END $$;



DO $$
DECLARE
  v_quiz_id_9 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الصوم ونوافل شهر رمضان والمفطرات', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_9;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما هو الحكم الشرعي لمن أفطر في شهر رمضان متعمداً بغير عذر شرعي؟', '["لا شيء عليه إن تاب","تجب عليه الكفارة المغلظة مع القضاء","يجب عليه الاستغفار فقط","يجب عليه القضاء فقط"]'::jsonb, 1, 20, 0, 'multi', 'من أفطر متعمداً في رمضان بغير عذر تجب عليه الكفارة المغلظة وهي عتق رقبة أو صيام شهرين متتابعين أو إطعام ستين مسكيناً مع وجوب القضاء، وفق المشهور من الفقه الجعفري.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما هي النية المعتبرة في صوم شهر رمضان وفق الفقه الجعفري؟', '["النية من أي وقت قبل الفجر أو بعده في أثناء النهار مطلقاً","يكفي القصد العام في أول الشهر عن جميع أيامه","النية بعد الزوال جائزة مطلقاً","النية قبل الفجر الصادق أو أثناء النهار قبل الزوال لمن لم يأت بمفطر"]'::jsonb, 3, 20, 1, 'multi', 'يشترط الفقه الجعفري تبييت النية قبل الفجر، وللناسي أو الجاهل أن ينوي قبل الزوال ما لم يأتِ بمفطر، وهو ما ذهب إليه السيد الخوئي والسيد السيستاني.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'أيٌّ من التالية يُعدّ من المفطرات عند الإمامية؟', '["شم الروائح العطرة","التبرع بالدم","الحقنة الشرجية","السباحة في الماء"]'::jsonb, 2, 20, 2, 'multi', 'الحقنة الشرجية مفطرة عند المشهور من فقهاء الإمامية لأنها إدخال شيء إلى الجوف، أما شم العطور والتبرع بالدم والسباحة فلا تُبطل الصوم على الأصح.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما حكم الصوم في السفر وفق الفقه الجعفري؟', '["يصح الصوم في السفر إن نذره قبل السفر فقط","يحرم الصوم في السفر ويجب القضاء","يتخير المسافر بين الصوم والإفطار","يجوز الصوم في السفر مطلقاً"]'::jsonb, 1, 20, 3, 'multi', 'ذهب المشهور من فقهاء الإمامية إلى بطلان صوم رمضان في السفر الذي توجب فيه قصر الصلاة، ويجب على المسافر الإفطار وقضاء تلك الأيام بعد رمضان.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما هي نوافل شهر رمضان الثابتة عند الإمامية في كل ليلة؟', '["ثماني ركعات","أربع ركعات","ست ركعات","عشرون ركعة"]'::jsonb, 3, 20, 4, 'multi', 'المشهور عند الإمامية استحباب عشرين ركعة في كل ليلة من ليالي رمضان، تُوزَّع على أوقات مخصوصة، وهي مستحبة لا واجبة، وقد وردت في روايات متعددة.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما حكم الارتماس في الماء للصائم عند الإمامية؟', '["محرم ومفطر عند المشهور","مفطر في النهار مباح في الليل","جائز مطلقاً","مكروه ولا يُفطر"]'::jsonb, 0, 20, 5, 'multi', 'ذهب المشهور من فقهاء الإمامية إلى أن الارتماس في الماء بغمس الرأس كله دفعةً واحدة مفطر ومحرم على الصائم، وهو رأي السيد الخوئي والسيد السيستاني.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما الحكم الشرعي لمن أجنب في ليل رمضان وتعمد تأخير الغسل حتى طلع الفجر؟', '["صومه صحيح ولا شيء عليه","صومه باطل ويجب القضاء فقط","يستحب له الاستغفار ولا شيء آخر","صومه باطل ويجب القضاء والكفارة"]'::jsonb, 1, 20, 6, 'multi', 'من تعمد البقاء على الجنابة حتى طلع الفجر في شهر رمضان بطل صومه عند المشهور من الإمامية ووجب عليه القضاء، واختلفوا في وجوب الكفارة والأحوط وجوبها.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما حكم إفطار المريض الذي يتضرر من الصوم في شهر رمضان؟', '["يجب عليه الصوم ولو بلغ الضرر حداً شديداً","يجوز له الإفطار ولا قضاء عليه","يتصدق عوضاً عن القضاء فقط","يجب عليه الإفطار ويقضي بعد زوال العذر"]'::jsonb, 3, 20, 7, 'multi', 'يجب على المريض الذي يتضرر من الصوم الإفطار، فإذا زال مرضه قبل انتهاء رمضان وجب عليه القضاء، أما من استمر مرضه حتى رمضان القادم فيسقط عنه القضاء وتجب الفدية.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'أيٌّ مما يلي لا يُعدّ من المفطرات في الفقه الجعفري؟', '["إيصال الغبار الغليظ إلى الحلق","الكذب على الله أو النبي أو الأئمة","شم الرياحين والأزهار","استعمال قطرة العين الواصلة إلى الحلق"]'::jsonb, 2, 20, 8, 'multi', 'شم الرياحين والأزهار لا يُفطر الصوم عند الإمامية، في حين أن إيصال الغبار الغليظ إلى الحلق عمداً والكذب على المعصومين والقطرة الواصلة إلى الحلق مفطرات عند المشهور.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما هي الليالي التي تُضاعف فيها نوافل رمضان ويُستحب فيها إحياؤها بالعبادة عند الإمامية؟', '["ليالي القدر وهي التاسعة عشرة والحادية والعشرون والثالثة والعشرون","ليالي الأيام الفردية فقط","ليالي الجمعة فقط","الليالي العشر الأولى فقط"]'::jsonb, 0, 20, 9, 'multi', 'تُعدّ ليالي القدر عند الإمامية هي ليلة التاسع عشر وليلة الحادي والعشرين وليلة الثالث والعشرين من رمضان، وتُستحب فيها العبادة والإحياء ويُضاعف فيها ثواب النوافل وفق الروايات المعتبرة.', 'فقه جعفري عملي');
END $$;

